	result, err := q.db.Exec(ctx, setDeliveryStatus,
		arg.NewStatus,
		arg.FailureReason,
		arg.CallAttempts,
		arg.ID,
		arg.FromStatuses,
	)
	if err != nil {
		return 0, err
	}
