const startAssignment = `-- name: StartAssignment :one

INSERT INTO assignment_requests (order_id) VALUES ($1)
ON CONFLICT (order_id) DO UPDATE SET closed_at = NULL
RETURNING order_id, started_at, offers_count, alerted_at, closed_at
`

// ---------------------------------------------------------------- attribution
// Démarre (ou rouvre après un désistement) la recherche d'un livreur pour une commande.
func (q *Queries) StartAssignment(ctx context.Context, orderID uuid.UUID) (AssignmentRequest, error) {
	row := q.db.QueryRow(ctx, startAssignment, orderID)
	var i AssignmentRequest
	err := row.Scan(
		&i.OrderID,
		&i.StartedAt,
		&i.OffersCount,
		&i.AlertedAt,
		&i.ClosedAt,
	)
	return i, err
}

